package com.bank.pitch.service;

import com.bank.pitch.model.CandidateProfile;
import java.util.logging.*;

// Renders the two-minute narrative and validates it has a measurable result.
public class PitchService {
    private final Logger log;

    public PitchService(Logger log) { this.log = log; }

    public void renderPitch(CandidateProfile p) {
        log.info(() -> "PRESENT: " + p.getPresent());

        if (!p.hasMeasurableResult()) {
            // A past block with no number is weak — warn, like a real audit check.
            log.warning("PAST block has no measurable result — add a number!");
        } else {
            double delta = p.getResultBefore() - p.getResultAfter();
            log.info(() -> "PAST: " + p.getPast()
                + " (improvement: " + delta + " percentage points)");
        }

        log.info(() -> "FUTURE: " + p.getFuture());
        log.info("Pitch complete — delivered in under two minutes.");
    }
}
