package com.bank.career.service;

import com.bank.career.model.CareerMove;
import java.util.List;
import java.util.logging.*;

// Flags grievance-based reasons and confirms forward-looking ones — like a fraud filter.
public class ReasonClassifier {
    private final Logger log;

    // Words that signal a grievance rather than a growth motive.
    private static final List<String> RED_FLAGS =
        List.of("mess", "never listened", "hate", "rude", "boring", "underpaid");

    public ReasonClassifier(Logger log) { this.log = log; }

    public void evaluate(CareerMove move) {
        String reason = move.getReason().toLowerCase();
        boolean grievance = RED_FLAGS.stream().anyMatch(reason::contains);

        if (grievance) {
            log.warning(() -> "GRIEVANCE reason detected — reframe it forward: \""
                + move.getReason() + "\"");
        } else if (move.getTargetRole() == null || move.getTargetRole().isBlank()
                   || move.getTargetRole().equalsIgnoreCase("Any new job")) {
            log.warning("No concrete destination role — name the scope you want.");
        } else {
            log.info(() -> "STRONG forward-looking reason. Moving from \""
                + move.getCurrentRole() + "\" toward \"" + move.getTargetRole() + "\".");
        }
    }
}
