package com.bank.weakness.service;

import com.bank.weakness.model.WeaknessPlan;
import java.util.logging.*;

// Rejects fake weaknesses and empty plans; accepts a genuine weakness with progress.
public class ImprovementCoach {
    private final Logger log;

    public ImprovementCoach(Logger log) { this.log = log; }

    public void evaluate(WeaknessPlan plan) {
        if (!plan.isGenuine()) {
            // A disguised strength erodes trust, like hiding a known debt.
            log.warning(() -> "FAKE weakness detected: \"" + plan.getWeakness()
                + "\" — pick a real, manageable limitation.");
            return;
        }
        if (!plan.hasPlan()) {
            log.warning(() -> "Genuine weakness but NO plan — pair it with concrete actions.");
            return;
        }
        log.info(() -> "GOOD answer — genuine weakness: " + plan.getWeakness());
        plan.getActions().forEach(a -> log.info(() -> "   action: " + a));
        log.info(() -> "   progress: " + plan.getProgressPercent() + "% — the fix is working.");
    }
}
