package com.bank.fit.service;

import com.bank.fit.model.CandidateBid;
import com.bank.fit.model.JobRequirement;
import java.util.logging.*;

// Scores how many of the role's needs the candidate can prove — fit by evidence.
public class FitScorer {
    private final Logger log;

    public FitScorer(Logger log) { this.log = log; }

    public void score(JobRequirement role, CandidateBid bid) {
        long matched = role.getNeeds().stream()
            .filter(bid.getProvenStrengths()::contains)   // need proven by candidate?
            .count();
        int total = role.getNeeds().size();
        double pct = 100.0 * matched / total;

        if (pct >= 75.0) {
            log.info(() -> bid.getName() + " candidate: STRONG fit — proves "
                + matched + " of " + total + " needs (" + pct + "%).");
        } else {
            log.warning(() -> bid.getName() + " candidate: WEAK fit — proves only "
                + matched + " of " + total + " needs (" + pct + "%). Map proof to needs.");
        }
    }
}
