package com.bank.motivation.service;

import com.bank.motivation.model.CandidateGoals;
import com.bank.motivation.model.CompanyProfile;
import java.util.logging.*;

// Checks that a reason is company-specific AND links an attribute to a personal goal.
public class MotivationMatcher {
    private final Logger log;

    public MotivationMatcher(Logger log) { this.log = log; }

    public void evaluate(CompanyProfile company, CandidateGoals goals, String reason) {
        String r = reason.toLowerCase();

        // Does the reason reference a specific, researched company attribute?
        boolean specific = company.getAttributes().stream()
            .anyMatch(attr -> r.contains(keyword(attr)));
        // Does it also connect to one of the candidate's goals (two-way match)?
        boolean twoWay = goals.getGoals().stream()
            .anyMatch(goal -> r.contains(keyword(goal)));

        if (specific && twoWay) {
            log.info(() -> "STRONG motivation — company-specific AND linked to a goal.");
        } else if (!specific) {
            log.warning(() -> "GENERIC reason — could be pasted onto any company. "
                + "Cite a specific attribute of " + company.getName() + ".");
        } else {
            log.warning(() -> "Company-specific but one-way — link it to your own goal.");
        }
    }

    // Take the first keyword of a phrase for a simple contains check.
    private String keyword(String phrase) {
        String[] parts = phrase.split(" ");
        return parts[parts.length - 1];   // e.g. "fraud platform" → "platform"
    }
}
