// ─── File: src/main/java/com/bank/incident/service/IncidentResponder.java ───
package com.bank.incident.service;

import java.util.logging.*;

// Runs the incident lifecycle: detect, stabilize, diagnose, fix, verify, prevent.
public class IncidentResponder {
    private final Logger log;
    private final TransferService transfers;

    public IncidentResponder(Logger log, TransferService transfers) {
        this.log = log;
        this.transfers = transfers;
    }

    public void handleIncident() {
        // 1. DETECT — read metrics, assess impact.
        log.severe(() -> "DETECT: transfers failing. Pool active="
            + transfers.getActive() + "/" + transfers.getPoolMax());

        // 2. STABILIZE — open the circuit breaker BEFORE knowing root cause.
        transfers.openCircuit();
        log.warning("STABILIZE: circuit breaker opened — stop the bleeding.");

        // 3. DIAGNOSE — use evidence: pool is saturated → exhaustion.
        if (transfers.isSaturated()) {
            log.severe("DIAGNOSE: connection pool exhausted by unbounded retries (root cause).");
        }

        // 4. FIX — cap retries so a storm cannot saturate the pool again.
        transfers.capRetries(3);
        transfers.drainPool();
        log.info(() -> "FIX: retries capped at " + transfers.getMaxRetries()
            + ", pool drained.");

        // 5. VERIFY — confirm the pool recovered.
        log.info(() -> "VERIFY: pool active=" + transfers.getActive()
            + "/" + transfers.getPoolMax() + " — healthy.");

        // 6. PREVENT — add an alert so it cannot recur silently.
        log.info("PREVENT: added alert on pool-usage > 80% and a retry-budget monitor.");
    }
}
