package com.bank.learn.service;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.*;

// A minimal publish/consume message bus standing in for the new technology.
public class MessageBus {
    private final Logger log;
    private final Deque<String> topic = new ArrayDeque<>();
    private int published = 0;
    private int consumed = 0;

    public MessageBus(Logger log) { this.log = log; }

    public void publish(String settlementEvent) {
        topic.addLast(settlementEvent);
        published++;
        log.fine(() -> "published: " + settlementEvent);
    }

    public String consume() {
        String e = topic.pollFirst();
        if (e != null) { consumed++; log.fine(() -> "consumed: " + e); }
        return e;
    }

    public int getPublished() { return published; }
    public int getConsumed() { return consumed; }
    public boolean isEmpty() { return topic.isEmpty(); }
}
