package com.bank.techchoice.service;

import com.bank.techchoice.model.TechOption;
import java.util.Comparator;
import java.util.List;
import java.util.logging.*;

// Applies project-specific weights, picks the winner, and names the loser's strength.
public class TechEvaluator {
    private final Logger log;

    // For a LEDGER: fit (ACID) and maturity (security) weighted heavily.
    private static final double W_FIT = 0.35;
    private static final double W_PERF = 0.15;
    private static final double W_TEAM = 0.15;
    private static final double W_MATURITY = 0.25;
    private static final double W_OPS = 0.10;

    public TechEvaluator(Logger log) { this.log = log; }

    public void choose(List<TechOption> options) {
        options.forEach(o -> log.info(() ->
            o.getName() + " score=" + String.format("%.2f", score(o))));

        TechOption winner = options.stream()
            .max(Comparator.comparingDouble(this::score)).orElseThrow();
        TechOption loser = options.stream()
            .min(Comparator.comparingDouble(this::score)).orElseThrow();

        log.info(() -> "CHOICE: " + winner.getName()
            + " (score=" + String.format("%.2f", score(winner)) + ")");
        // Fairly acknowledge the losing option's genuine strength.
        log.info(() -> "Fair note — " + loser.getName()
            + " was strong at: " + loser.getStrength());
    }

    private double score(TechOption o) {
        return W_FIT * o.getFit() + W_PERF * o.getPerformance()
             + W_TEAM * o.getTeamSkill() + W_MATURITY * o.getMaturity()
             + W_OPS * o.getOpsCost();
    }
}
