package com.bank.complexity.service;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.logging.*;

// A ledger that applies transfers idempotently — the key to exactly-once correctness.
public class Ledger {
    private final Logger log;
    private final Map<String, BigDecimal> balances = new HashMap<>();
    private final Set<String> appliedRequestIds = new HashSet<>();  // dedupe key

    public Ledger(Logger log) { this.log = log; }

    public void open(String accountId, BigDecimal opening) {
        balances.put(accountId, opening);
    }

    // Idempotent: a repeated requestId is ignored, so retries never double-apply.
    public synchronized boolean apply(String requestId, String from, String to, BigDecimal amount) {
        if (appliedRequestIds.contains(requestId)) {
            log.warning(() -> "DEDUPE: " + requestId + " already applied — skipping (idempotent).");
            return false;
        }
        BigDecimal fromBal = balances.get(from);
        if (fromBal.compareTo(amount) < 0) {
            log.severe(() -> "INSUFFICIENT FUNDS for " + from);
            return false;
        }
        balances.put(from, fromBal.subtract(amount));
        balances.put(to, balances.get(to).add(amount));
        appliedRequestIds.add(requestId);     // mark applied AFTER success
        log.info(() -> "APPLIED " + requestId + ": " + from + "->" + to + " Rs." + amount);
        return true;
    }

    public BigDecimal balanceOf(String accountId) { return balances.get(accountId); }
}
