package com.bank.disagree.service;

import com.bank.disagree.model.Proposal;
import java.util.logging.*;

// Resolves on evidence, records the dissent, and commits the team — disagree & commit.
public class DisagreementResolver {
    private final Logger log;
    private static final int SLA_MS = 1000;   // the SLA both sides must respect

    public DisagreementResolver(Logger log) { this.log = log; }

    public void resolve(Proposal a, Proposal b) {
        // Critique the IDEA on data, never the person.
        log.info(() -> a.getAuthor() + " proposes " + a.getDesign()
            + " (measured p99=" + a.getMeasuredP99Ms() + "ms)");
        log.info(() -> b.getAuthor() + " proposes " + b.getDesign()
            + " (measured p99=" + b.getMeasuredP99Ms() + "ms)");

        // Decide by evidence: lower p99 that respects the SLA wins.
        Proposal winner = a.getMeasuredP99Ms() <= b.getMeasuredP99Ms() ? a : b;
        Proposal other = winner == a ? b : a;

        log.info(() -> "DECISION (evidence-based): " + winner.getDesign()
            + " — p99 " + winner.getMeasuredP99Ms() + "ms vs SLA " + SLA_MS + "ms.");

        // Record the dissent for accountability (concern on the record).
        log.warning(() -> "DISSENT RECORDED — " + other.getAuthor()
            + " raised: " + other.getNote());

        // Disagree-and-commit: the overruled side now fully supports the decision.
        log.info(() -> other.getAuthor()
            + " commits fully to " + winner.getDesign() + ". Team moves forward together.");
    }
}
