        BurndownPolicy policy = new BurndownPolicy(2);

        // Simulate a sprint that starts fine then falls behind due to the audit dependency.
        int[] completedByDay = {2, 4, 5, 6, 7, 8, 9, 11, 14, 17};
        for (int day = 1; day <= sprintDays; day++) {
            tracker.record(new DayProgress(day, completedByDay[day - 1]));
            int actualRemaining = tracker.remainingTasks();
            int idealRemaining = tracker.idealRemaining(day);
            boolean atRisk = policy.isAtRisk(actualRemaining, idealRemaining);
            if (atRisk) {
                log.warning(() -> "Day " + tracker.lastDay() + ": AT RISK — behind by "
                        + (tracker.remainingTasks() - tracker.idealRemaining(tracker.lastDay()))
                        + " tasks. Communicate and re-scope now.");
            } else {
                log.info(() -> "Day " + tracker.lastDay() + ": on track, "
                        + tracker.remainingTasks() + " tasks remaining.");
            }
        }

