class DayProgress {
    private final int day;
    private final int cumulativeCompleted;

    DayProgress(int day, int cumulativeCompleted) {
        this.day = day;
        this.cumulativeCompleted = cumulativeCompleted;
    }

    int getDay() { return day; }
    int getCumulativeCompleted() { return cumulativeCompleted; }
}

// ─── Would be in tracker/SprintTracker.java in a real project ───
class SprintTracker {
    private static final Logger log = Logger.getLogger(SprintTracker.class.getName());
    private final int totalTasks;
    private final int sprintDays;
    private final List<DayProgress> history = new ArrayList<>();

    SprintTracker(int totalTasks, int sprintDays) {
        this.totalTasks = totalTasks;
        this.sprintDays = sprintDays;
    }

    void record(DayProgress progress) {
        history.add(progress);
        log.fine(() -> "Recorded day " + progress.getDay()
                + ", completed=" + progress.getCumulativeCompleted());
    }

    int lastDay() {
        return history.get(history.size() - 1).getDay();
    }

    int remainingTasks() {
        int done = history.get(history.size() - 1).getCumulativeCompleted();
        return totalTasks - done;
    }

    // Ideal remaining work on a given day assumes even progress across the sprint.
    int idealRemaining(int day) {
        double perDay = (double) totalTasks / sprintDays;
        int idealDone = (int) Math.round(perDay * day);
        return Math.max(0, totalTasks - idealDone);
    }
}

// ─── Would be in policy/BurndownPolicy.java in a real project ───
class BurndownPolicy {
    private final int atRiskThreshold;

    BurndownPolicy(int atRiskThreshold) {
        this.atRiskThreshold = atRiskThreshold;
    }

    boolean isAtRisk(int actualRemaining, int idealRemaining) {
        return (actualRemaining - idealRemaining) >= atRiskThreshold;
    }
}

