        this.id = id;
        this.from = from;
        this.to = to;
        this.amount = amount;
    }

    String getId() { return id; }
    String getFrom() { return from; }
    String getTo() { return to; }
    BigDecimal getAmount() { return amount; }
    boolean isValid() { return amount.compareTo(BigDecimal.ZERO) > 0; }
}

// ─── Would be in processor/OneAtATimeProcessor.java in a real project ───
// The old approach: process each transfer, and the first bad one halts the run.
class OneAtATimeProcessor {
    private static final Logger log = Logger.getLogger(OneAtATimeProcessor.class.getName());

    void process(List<Transfer> transfers) {
        int done = 0;
        for (Transfer t : transfers) {
            if (!t.isValid()) {
                log.severe(() -> "HALTED at " + t.getId() + " (invalid amount " + t.getAmount()
                        + "). Remaining transfers not attempted.");
                log.warning(() -> "Processed " + done + " of " + transfers.size()
                        + " before stopping.");
                return;
            }
            done++;
            log.info(() -> "Settled " + t.getId());
        }
    }
}

// ─── Would be in processor/BatchProcessor.java in a real project ───
// The new approach: validate everything first, settle valid ones, report all failures.
class BatchProcessor {
    private static final Logger log = Logger.getLogger(BatchProcessor.class.getName());

    void process(List<Transfer> transfers) {
        List<String> failures = new ArrayList<>();
        for (Transfer t : transfers) {
            if (!t.isValid()) {
                failures.add(t.getId() + " (amount " + t.getAmount() + ")");
            }
        }
        int settled = 0;
        for (Transfer t : transfers) {
            if (t.isValid()) {
                settled++;
                log.info(() -> "Settled " + t.getId());
            }
        }
        final int settledCount = settled;
        log.info(() -> "Batch settled " + settledCount + " of " + transfers.size() + " transfers.");
        if (!failures.isEmpty()) {
            log.warning(() -> "All failures surfaced at once: " + failures);
        }
    }
}

