class BulkUpdater {
    private static final Logger log = Logger.getLogger(BulkUpdater.class.getName());
    private final List<Account> accounts;

    BulkUpdater(List<Account> accounts) {
        this.accounts = accounts;
    }

    // Dry run: report impact, change nothing.
    int dryRun(Predicate<Account> filter) {
        int count = 0;
        for (Account a : accounts) {
            if (filter.test(a)) {
                count++;
                log.fine(() -> "WOULD set interestFlag=true for " + a.getAccountId());
            }
        }
        return count;
    }

    // Apply: change data, but only with dry-run done and explicit confirmation.
    int apply(Predicate<Account> filter, boolean dryRunCompleted, boolean confirmed) {
        if (!dryRunCompleted || !confirmed) {
            log.severe("Refusing to apply: dry run and confirmation are required.");
            return 0;
        }
        int count = 0;
        for (Account a : accounts) {
            if (filter.test(a)) {
                a.setInterestFlag(true);
                count++;
                log.info(() -> "Set interestFlag=true for " + a.getAccountId());
            }
        }
        return count;
    }
}

