class TaskRecord {
    private final String name;
    private final BigDecimal estimatedDays;
    private final BigDecimal actualDays;

    TaskRecord(String name, BigDecimal estimatedDays, BigDecimal actualDays) {
        this.name = name;
        this.estimatedDays = estimatedDays;
        this.actualDays = actualDays;
    }

    String getName() { return name; }
    BigDecimal getEstimatedDays() { return estimatedDays; }
    BigDecimal getActualDays() { return actualDays; }
}

// ─── Would be in tracker/EstimationTracker.java in a real project ───
class EstimationTracker {
    private static final Logger log = Logger.getLogger(EstimationTracker.class.getName());
    private final List<TaskRecord> records = new ArrayList<>();

    void record(TaskRecord record) {
        records.add(record);
        log.fine(() -> "Recorded " + record.getName() + ": est="
                + record.getEstimatedDays() + " actual=" + record.getActualDays());
    }

    // Average of (actual / estimated) across all recorded tasks.
    BigDecimal calibrationFactor() {
        if (records.isEmpty()) {
            return BigDecimal.ONE;
        }
        BigDecimal sumRatio = BigDecimal.ZERO;
        for (TaskRecord r : records) {
            BigDecimal ratio = r.getActualDays()
                    .divide(r.getEstimatedDays(), 4, RoundingMode.HALF_EVEN);
            sumRatio = sumRatio.add(ratio);
        }
        return sumRatio.divide(new BigDecimal(records.size()), 2, RoundingMode.HALF_EVEN);
    }

    // Apply the calibration factor to a fresh raw estimate.
    BigDecimal calibrate(BigDecimal rawEstimate) {
        return rawEstimate.multiply(calibrationFactor()).setScale(1, RoundingMode.HALF_EVEN);
    }
}

