class ReconciliationMonitor {
    private static final Logger log = Logger.getLogger(ReconciliationMonitor.class.getName());
    private final Duration expectedInterval;

    ReconciliationMonitor(Duration expectedInterval) {
        this.expectedInterval = expectedInterval;
    }

    boolean check(JobStatus status, LocalDateTime now) {
        Duration sinceSuccess = Duration.between(status.getLastSuccess(), now);
        if (sinceSuccess.compareTo(expectedInterval) > 0) {
            log.severe(() -> "ALERT: " + status.getJobName() + " overdue. Last success "
                    + sinceSuccess.toHours() + "h ago (expected within "
                    + expectedInterval.toHours() + "h). Paging on-call.");
            return false;
        }
        log.info(() -> status.getJobName() + " healthy. Last success "
                + sinceSuccess.toHours() + "h ago.");
        return true;
    }
}

