        options.add(new DecisionOption("Pause transfers", 50000, true));

        DecisionHelper helper = new DecisionHelper(true);
        DecisionOption chosen = helper.recommend(options);

        log.info(() -> "Recommended action under uncertainty: " + chosen.getName()
