// ─── Would be in projector/TrendProjector.java in a real project ───
class TrendProjector {
    private static final Logger log = Logger.getLogger(TrendProjector.class.getName());
    private final int limit;
    private final int warnDaysThreshold;

    TrendProjector(int limit, int warnDaysThreshold) {
        this.limit = limit;
        this.warnDaysThreshold = warnDaysThreshold;
    }

    // Average increase per day across the readings.
    double dailyGrowth(List<UsageReading> readings) {
        if (readings.size() < 2) {
            return 0.0;
        }
        int first = readings.get(0).getValue();
        int last = readings.get(readings.size() - 1).getValue();
        int days = readings.get(readings.size() - 1).getDay() - readings.get(0).getDay();
        return days == 0 ? 0.0 : (double) (last - first) / days;
    }

    // How many days until usage reaches the limit at the current growth rate.
    int daysToLimit(List<UsageReading> readings) {
        double growth = dailyGrowth(readings);
        if (growth <= 0) {
            return Integer.MAX_VALUE;
        }
        int current = readings.get(readings.size() - 1).getValue();
        return (int) Math.ceil((limit - current) / growth);
    }

    boolean isConcerning(List<UsageReading> readings) {
        return daysToLimit(readings) <= warnDaysThreshold;
    }
}

