        return req.getAmount().multiply(new BigDecimal("0.001"));
    }
}

// ─── Would be in calc/NewTransferCalculator.java in a real project ───
// The new service. Should match the old logic. forceBug simulates a regression.
class NewTransferCalculator {
    BigDecimal fee(TransferRequest req) {
        if (req.isForceBug()) {
            return req.getAmount().multiply(new BigDecimal("0.002")); // wrong — double fee
        }
        return req.getAmount().multiply(new BigDecimal("0.001"));
    }
}

// ─── Would be in router/MigrationRouter.java in a real project ───
class MigrationRouter {
    private static final Logger log = Logger.getLogger(MigrationRouter.class.getName());
    private final OldTransferCalculator oldCalc;
    private final NewTransferCalculator newCalc;
    private final int rolloutPercent;
    private final boolean verifyParity;
    private int requestCounter = 0;
    private int mismatchCount = 0;

    MigrationRouter(OldTransferCalculator oldCalc, NewTransferCalculator newCalc,
                    int rolloutPercent, boolean verifyParity) {
        this.oldCalc = oldCalc;
        this.newCalc = newCalc;
        this.rolloutPercent = rolloutPercent;
        this.verifyParity = verifyParity;
    }

    BigDecimal route(TransferRequest req) {
        requestCounter++;
        BigDecimal oldFee = oldCalc.fee(req);

        if (verifyParity) {
            BigDecimal newFee = newCalc.fee(req);
            if (oldFee.compareTo(newFee) != 0) {
                mismatchCount++;
                log.severe(() -> "PARITY MISMATCH on " + req.getId() + ": old=" + oldFee
                        + " new=" + newFee + ". Serving OLD result, blocking rollout increase.");
                return oldFee;
            }
        }

        boolean useNew = (requestCounter * 100) % 100 < rolloutPercent
                || (requestCounter % (100 / Math.max(1, rolloutPercent)) == 0);
        if (useNew) {
            log.info(() -> req.getId() + " served by NEW service (parity verified), fee=" + oldFee);
        } else {
            log.info(() -> req.getId() + " served by OLD service, fee=" + oldFee);
        }
        return oldFee;
    }

    int getMismatchCount() { return mismatchCount; }
}

