    int evaluate(StarStory s) {
        int score = 0;
        if (notBlank(s.getSituation())) {
            score++;
        } else {
            log.warning("Missing Situation — set the scene briefly.");
        }
        if (notBlank(s.getTask())) {
            score++;
        } else {
            log.warning("Missing Task — state YOUR specific responsibility.");
        }
        if (notBlank(s.getAction())) {
            score++;
            if (!s.getAction().contains("I ")) {
                log.warning("Action is not first-person — say what YOU did, not 'we'.");
            }
        } else {
