        }
        if (notBlank(s.getResult()) && s.isResultQuantified()) {
            score++;
        } else {
            log.warning("Result not measurable — add a number (ms saved, % improved, errors reduced).");
        }
        final int finalScore = score;
        log.info(() -> "STAR completeness: " + finalScore + "/4 "
                + (finalScore == 4 ? "— interview ready." : "— needs work."));
        return score;
    }

    private boolean notBlank(String s) {
