class PreparedStory {
    private final String title;
    private final Set<String> categories;

    PreparedStory(String title, Set<String> categories) {
        this.title = title;
        this.categories = categories;
    }

    String getTitle() { return title; }
    Set<String> getCategories() { return categories; }
    boolean covers(String category) { return categories.contains(category); }
}

// ─── Would be in bank/StoryBank.java in a real project ───
class StoryBank {
    private static final Logger log = Logger.getLogger(StoryBank.class.getName());
    private final List<PreparedStory> stories = new ArrayList<>();

    void add(PreparedStory story) {
        stories.add(story);
        log.fine(() -> "Added story '" + story.getTitle() + "' covering " + story.getCategories());
    }

    // Return the story covering this category that covers the most categories overall,
    // so you reuse your richest material.
    PreparedStory bestFor(String category) {
        PreparedStory best = null;
        for (PreparedStory s : stories) {
            if (s.covers(category)) {
                if (best == null || s.getCategories().size() > best.getCategories().size()) {
                    best = s;
                }
            }
        }
        return best;
    }

    PreparedStory mostVersatile() {
        PreparedStory best = null;
        for (PreparedStory s : stories) {
            if (best == null || s.getCategories().size() > best.getCategories().size()) {
                best = s;
            }
        }
        return best;
    }
}

